// University-level experiments. Each keeps the school topic that it grows from in `nodes`.
export const advancedLabs=[
 {id:'gps',title:'衛星の距離から現在地を解く',icon:'◎ ◎ ◎',category:'大学の数学 · 衛星測位',question:'円は1点で交わらない。それでも位置が決まるのはなぜ？',nodes:['gps','least-squares','pythagorean','circle','matrix','artificial-satellite'],controls:[['rx','受信機の本当の横位置',-6,6,.5,2.5,''],['clock','受信機の時計のずれ（距離に換算）',0,3,.1,1.5,''],['noise','距離の測定誤差（最大）',0,.6,.05,0,''],['count','使う衛星の数',3,6,1,4,'機'],['iter','解き直した回数',0,8,1,8,'回']],formula:'<msub><mi>ρ</mi><mi>i</mi></msub><mo>=</mo><msqrt><msup><mrow><mo>(</mo><mi>x</mi><mo>−</mo><msub><mi>x</mi><mi>i</mi></msub><mo>)</mo></mrow><mn>2</mn></msup><mo>+</mo><msup><mrow><mo>(</mo><mi>y</mi><mo>−</mo><msub><mi>y</mi><mi>i</mi></msub><mo>)</mo></mrow><mn>2</mn></msup></msqrt><mo>+</mo><mi>b</mi><mspace width="1em"/><munder><mo>min</mo><mrow><mi>x</mi><mo>,</mo><mi>y</mi><mo>,</mo><mi>b</mi></mrow></munder><munder><mo>∑</mo><mi>i</mi></munder><msup><mrow><mo>(</mo><msub><mi>ρ</mi><mi>i</mi></msub><mo>−</mo><msub><mover><mi>ρ</mi><mo>^</mo></mover><mi>i</mi></msub><mo>)</mo></mrow><mn>2</mn></msup>',lesson:'時計のずれbも未知数にすると、ずれた円からでも位置が決まる。',everyday:'スマホの時計は衛星の原子時計ほど正確ではありません。そこで位置と一緒に時計のずれも未知数として解きます。実際のGPSは3次元なので、x・y・zとbの4つを求めるために4機以上の衛星を使います。',limit:'平面に縮めた教材モデルで、距離は相対単位。衛星の位置は固定、光の速さ×時計のずれを距離bとして加えます。解き方はガウス・ニュートン法による非線形最小二乗法（初期値は(0,3)）。大気による遅れ・衛星の時計誤差・地球の自転などは含みません。ρᵢは測った距離、ρ̂ᵢは推定位置から計算した距離。',renderer:'advanced'},
 {id:'hamming',title:'壊れたデータを自分で直す',icon:'0 1 ✓',category:'大学の情報 · 符号理論',question:'どこか1ビット壊れても、受け取った側が場所を当てて直せる？',nodes:['error-correction','coding-theory','binary','matrix','qr-code'],controls:[],formula:'<mi mathvariant="bold">s</mi><mo>=</mo><mi>H</mi><msup><mi mathvariant="bold">c</mi><mi>T</mi></msup><mspace width="0.4em"/><mo>(</mo><mi>mod</mi><mspace width="0.2em"/><mn>2</mn><mo>)</mo>',lesson:'3つの円の偶奇の組み合わせが、壊れた位置の番号そのものになる。',everyday:'QRコードが少し汚れても読めるのは、誤り訂正の符号を使っているから。実際のQRコードはハミング符号より強いリード・ソロモン符号を使いますが、「余分な情報で誤りを見つけて直す」考え方は同じです。',limit:'ハミング(7,4)符号。4ビットの情報に3ビットの検査用ビットを足した7ビットを送ります。1か所の誤りは必ず訂正できますが、2か所壊れると別の位置を「直して」しまうことがあります。Hは3×7の検査行列、cは受け取った7ビット、sは3ビットの症状（シンドローム）。',renderer:'advanced'},
 {id:'rsa',title:'公開した鍵で秘密を送る',icon:'🔑 mod',category:'大学の数学 · 整数論と暗号',question:'鍵をみんなに見せても、読めるのは自分だけ？',nodes:['data-encryption','number-theory','prime-factorization','division','internet'],controls:[['p','秘密の素数 p（何番目）',0,20,1,8,''],['q','秘密の素数 q（何番目）',0,20,1,11,'']],formula:'<mi>c</mi><mo>=</mo><msup><mi>m</mi><mi>e</mi></msup><mspace width="0.3em"/><mi>mod</mi><mspace width="0.3em"/><mi>n</mi><mspace width="1em"/><mi>m</mi><mo>=</mo><msup><mi>c</mi><mi>d</mi></msup><mspace width="0.3em"/><mi>mod</mi><mspace width="0.3em"/><mi>n</mi><mspace width="1em"/><mi>e</mi><mi>d</mi><mo>≡</mo><mn>1</mn><mspace width="0.3em"/><mo>(</mo><mi>mod</mi><mspace width="0.3em"/><mo>(</mo><mi>p</mi><mo>−</mo><mn>1</mn><mo>)</mo><mo>(</mo><mi>q</mi><mo>−</mo><mn>1</mn><mo>)</mo><mo>)</mo>',lesson:'nを素因数分解できればdが分かる。安全さは素因数分解の難しさにかかっている。',everyday:'httpsで始まるサイトとの通信では、最初の鍵の受け渡しや本人確認に公開鍵暗号が使われます。RSAはその代表的な方式の一つで、実際には2048ビット（約617桁）以上のnを使います。',limit:'1文字をA=1〜Z=26の数として、そのまま暗号化する教材用のRSAです。実用のRSAは巨大な素数と、同じ文字が同じ暗号にならないようにする処理（パディング）を必ず使います。この大きさの鍵は一瞬で破れるので、実際の秘密には使えません。mは平文、cは暗号文、eは公開指数、dは秘密指数、nは公開する法。',renderer:'advanced'},
 {id:'pathfinding',title:'最短の道を探す',icon:'S ⇢ G',category:'大学の情報 · グラフ探索',question:'全部のマスを調べなくても、最短の道は見つかる？',nodes:['game-pathfinding','graph-theory','algorithm','pythagorean'],controls:[['weight','ゴールまでの見積もりの重み w',0,3,.25,1,'']],formula:'<mi>f</mi><mo>(</mo><mi>v</mi><mo>)</mo><mo>=</mo><mi>g</mi><mo>(</mo><mi>v</mi><mo>)</mo><mo>+</mo><mi>w</mi><mo>·</mo><mi>h</mi><mo>(</mo><mi>v</mi><mo>)</mo><mspace width="1em"/><mi>h</mi><mo>(</mo><mi>v</mi><mo>)</mo><mo>=</mo><msqrt><mi>Δ</mi><msup><mi>x</mi><mn>2</mn></msup><mo>+</mo><mi>Δ</mi><msup><mi>y</mi><mn>2</mn></msup></msqrt>',lesson:'直線距離でゴールの方角を見積もると、調べるマスが減る。見積もりを大きくしすぎると最短ではなくなる。',everyday:'ゲームのキャラクターが壁をよけて歩くときや、地図アプリの経路検索の基本に、この種の探索が使われます。実際の地図アプリは道路網のグラフに前処理を加え、さらに速く探します。',limit:'24×14マス、上下左右と斜めの8方向。斜めは√2、壁の角をすり抜ける斜め移動は禁止。w=0はダイクストラ法、w=1はA*探索（直線距離は実際の距離を超えないので最短が保証される）、w>1は重み付きA*で、速い代わりに最短の保証がありません。g(v)は出発点からの距離、h(v)はゴールまでの直線距離。',renderer:'advanced'},
 {id:'neural',title:'ニューラルネットワークに境界を学ばせる',icon:'○→●',category:'大学の情報 · 機械学習',question:'中間の層がないと、どうしても分けられない形がある？',nodes:['neural-network','machine-learning','optimization','calculus','function'],controls:[['hidden','中間層のニューロン数',0,8,1,4,'個'],['rate','学習率 η',.05,2,.05,.5,'']],formula:'<mi>w</mi><mo>←</mo><mi>w</mi><mo>−</mo><mi>η</mi><mfrac><mrow><mo>∂</mo><mi>L</mi></mrow><mrow><mo>∂</mo><mi>w</mi></mrow></mfrac><mspace width="1em"/><mi>L</mi><mo>=</mo><mo>−</mo><mfrac><mn>1</mn><mi>N</mi></mfrac><munder><mo>∑</mo><mi>k</mi></munder><mo>[</mo><msub><mi>t</mi><mi>k</mi></msub><mi>log</mi><msub><mi>y</mi><mi>k</mi></msub><mo>+</mo><mo>(</mo><mn>1</mn><mo>−</mo><msub><mi>t</mi><mi>k</mi></msub><mo>)</mo><mi>log</mi><mo>(</mo><mn>1</mn><mo>−</mo><msub><mi>y</mi><mi>k</mi></msub><mo>)</mo><mo>]</mo>',lesson:'中間層0個では直線でしか分けられない。ニューロンを足すと曲がった境界を作れる。',everyday:'画像認識や音声認識のAIも、同じく「誤差を微分して、減る向きに重みを少し動かす」ことを大量のデータで繰り返して学習します。規模は何十億もの重みになりますが、1歩の考え方はこの体験と同じです。',limit:'入力2つ（点の座標）、tanhの中間層1層、出力はシグモイドで「青である確率」。全データを使う勾配降下法、誤差は交差エントロピー。重みの初期値は固定の乱数。学習率が大きすぎると誤差が振動することがあります。ηは学習率、tₖは正解（0か1）、yₖは予測。',renderer:'advanced'},
 {id:'pagerank',title:'リンクから重要なページを決める',icon:'⇄ ★',category:'大学の数学 · 線形代数と確率',question:'たくさんリンクされるページほど大事？ それだけで決まる？',nodes:['search-engine','markov-chain','linear-algebra','matrix','probability'],controls:[['damping','リンクをたどり続ける確率 d',.5,.95,.05,.85,''],['step','配り直した回数',0,40,1,0,'回']],formula:'<msub><mi>r</mi><mi>j</mi></msub><mo>=</mo><mfrac><mrow><mn>1</mn><mo>−</mo><mi>d</mi></mrow><mi>N</mi></mfrac><mo>+</mo><mi>d</mi><munder><mo>∑</mo><mrow><mi>i</mi><mo>→</mo><mi>j</mi></mrow></munder><mfrac><msub><mi>r</mi><mi>i</mi></msub><msub><mi>L</mi><mi>i</mi></msub></mfrac>',lesson:'重要なページからのリンクほど重く数える。配り直しを繰り返すと値が落ち着く。',everyday:'ページランクは初期のGoogle検索で順位づけの中心になった考え方です。現在の検索エンジンは、ほかにも非常に多くの手がかりを組み合わせて順位を決めています。',limit:'6ページの小さなリンク構造。ランダムにリンクをたどる閲覧者が、確率dでリンクをたどり、1−dで無作為なページへ飛ぶとします（ランダムサーファーモデル）。リンクを持たないページからは全ページへ均等に移ります。rⱼはページjの値、Lᵢはページiから出るリンク数、Nはページ数。',renderer:'advanced'},
];
